contract InvMutTest {
    C c;
    address deployer;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount to forward into c via c.go{value: amount}()
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to fund call");

        // record balances before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        bool reverted;
        // call go sending `amount` wei
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;
        uint selfBalAfter = address(this).balance;

        // General rule: owner is unchanged, and C's balance is zero after the call
        // (C must forward any held Ether out whether the external call reverted or not).
        assert(ownerAfter == ownerBefore && cBalAfter == 0);
    }

    // allow receiving Ether forwarded from C
    receive() external payable {}
}

